{"title":"Biomes","type":"vega","aggs":[],"params":{"spec":"/*
Authors:
  Dave Klingler
  Nicholas Donovan
  Shelby Hiens
  Jordan Waggoner


Questions:
  - Functionality on the IP address filter
    - Should the filter only filter on src instead that way we can see any destination from an IP (it does this sometimes??)
  - In-Viz filters are added due to opensearch filters refreshing the whole page whenever they are updated/deleted (SBH)

Todo:
  - Change fracCenter/start/end calls to compute in dataset (NGD)

*/

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {"type": "fit-x", "resize": true, "contains": "padding"},
  "config": {
    "signals": [
      {
        "name": "test",
        "update": "-if(width < 1060, 120, 80)"
      }
    ],
    "legend": {
      "layout": {
        "bottom": {
          "anchor": "end",
          "offset": {"signal": "-if(width < 1060, 120, 80)"}
        }
      }
    }
  },
  "signals": [
    {
      "name": "height",
      "init": "clamp(containerSize()[1], 460, containerSize()[1]) - 10"
    },
    {
      "name": "width",
      "init": "clamp(containerSize()[0], 850, containerSize()[0])"
    },
    {
      "name": "topPad",
      "init": "36"
    },
    {
      "name": "bottomPad",
      "init": "if(width < 1060, 108 + 40, 108)"
    },
    {
      "name": "usableHeight",
      "init": "height + padding.bottom - topPad - bottomPad"
    },
    {"name": "leftPad", "value": 40},
    {"name": "rightPad", "value": 40},
    {"name": "usableWidth", "update": "width - leftPad - rightPad"},
    {
      "name": "goldenRatio",
      "value": "0.6180339887"
    },
    {
      "name": "linkColorLegendMapping",
      "update": "{'ICS-GEN': 'ICS-General', 'DMZ-GEN': 'DMZ-General', 'GEN-GEN': 'General-General', 'GEN-DMZ': 'General-DMZ', 'GEN-ICS': 'General-ICS'}"
    },
    {
      "name": "zoneColorLegendMapping",
      "update": "{'GEN': 'General'}"
    },
    {"name": "textPrimary", "value": "#e2e8f0"},
    {"name": "legendTitle", "value": "#94a3b8"},
    {"name": "legendLabel", "value": "#e2e8f0"},
    {"name": "tooltipBg", "value": "#020617"},
    {"name": "tooltipText", "value": "#e2e8f0"},
    {"name": "tooltipMuted", "value": "#cbd5e1"},
    {
      "name": "minConnections",
      "value": 1,
      "bind": {"input": "range", "min": 1, "max": 20, "step": 1, "name": "Min Connections: "}
    },
    {
      "name": "ipFilter",
      "value": "",
      "bind": {
        "input": "text",
        "debounce": 800, // waits before updating
        "placeholder": "e.g. 10.0.0.0",
        "name": "IP Filter: "
      }
    },
    {   // keeping these filters until the persistent IP/filters problem is solved
      "name": "protoFilter",
      "value": "",
      "bind": {
        "input": "search",
        "placeholder": "e.g. bacnet",
        "name": "Protocol Filter: ",
        "debounce": 800
      }
    },
    {
      "name": "excludeSubnets",
      "value": "",
      "bind": {
        "input": "search",
        "placeholder": "e.g. 192.168.1",
        "name": "Exclude Subnet: ",
        "debounce": 800
      }
    },
    {
      "name": "excludeProtos",
      "value": "",
      "bind": {
        "input": "search",
        "placeholder": "e.g. dns",
        "name": "Exclude Protocol: ",
        "debounce": 800
      }
    },
    {
      "name": "showFilesOnly",
      "value": false,
      "bind": {
        "input": "checkbox", "name": "Show Files Only"
      }
    },
    // {
    //   "name": "hideFileLinks",
    //   "value": false,
    //   "bind": {
    //     "input": "checkbox", "name": "Hide File Links"
    //   }
    // },
    {
      "name": "lineType",
      "value": "double",
      "bind": {
        "input": "radio", "options": ["double", "arrow"], "labels": ["Double Line", "Arrows"], "name": "Line Type"
      }
    },
    // This can also be implemented with opensearch filter adds, thoughts?
    {
      "name": "ipType",
      "value": "both",
      "bind": {
        "input": "radio", "options": ["both", "ipv4", "ipv6"], "labels": ["Both", "IPv4", "IPv6"], "name": "IP Type"
      }
    },
    {
      "name": "genIcsOnly", "value": false,
      "on": [{"events": "@genics-btn:click, @genics-label:click", "update": "!genIcsOnly"}]
    },
    {
      "name": "dmzIcsOnly", "value": false,
      "on": [{"events": "@dmzics-btn:click, @dmzics-label:click", "update": "!dmzIcsOnly"}]
    },
    {
      "name": "fullChainOnly", "value": false,
      "on": [{"events": "@chain-btn:click, @chain-label:click", "update": "!fullChainOnly"}]
    },
    {
      "name": "hideSameZoneLinks", "value": false,
      "on": [{"events": "@samezone-btn:click, @samezone-label:click", "update": "!hideSameZoneLinks"}]
    },
    {
      "name": "dragStartX",
      "value": 0,
      "on": [{"events": "@nodeSymbols:mousedown", "update": "x()", "force": true}]
    },
    {
      "name": "dragStartY",
      "value": 0,
      "on": [{"events": "@nodeSymbols:mousedown", "update": "y()", "force": true}]
    },
    {
      "name": "suppressClick",
      "value": false,
      "on": [
        {"events": "@nodeSymbols:mousedown", "update": "false", "force": true},
        {
          "events": "window:mousemove",
          "update": "dragActive && dragId != null && (abs(x() - dragStartX) > 3 || abs(y() - dragStartY) > 3) ? true : suppressClick",
          "force": true
        }
      ]
    },
    {
      "name": "clickedNode",
      "value": null,
      "on": [
        {
          "events": "@nodeSymbols:click",
          "update": "suppressClick || !datum || !datum.id || datum.hasFiles ? clickedNode : clickedNode === datum.id ? null : datum.id",
          "force": true
        },
        {
          "events": "@collapsedBadge:click",
          "update": "suppressClick ? clickedNode : null",
          "force": true
        }
      ]
    },
    {
      "name": "selectedFileNode",
      "value": null,
      "on": [
        {
          "events": "@nodeSymbols:click",
          "update": "suppressClick || !datum || !datum.hasFiles ? selectedFileNode : (selectedFileNode === datum.id ? null : datum.id)",
          "force": true
        },
        {
          "events": "@file-detail-close:click",
          "update": "null",
          "force": true
        }
      ]
    },
    {
      "name": "dragId",
      "value": null,
      "on": [
        {"events": "@nodeSymbols:mousedown", "update": "datum && datum.id ? datum.id : null", "force": true},
        {"events": "window:mouseup", "update": "null", "force": true}
      ]
    },
    {
      "name": "dragActive",
      "value": false,
      "on": [
        {"events": "@nodeSymbols:mousedown", "update": "datum && datum.id ? true : false", "force": true},
        {"events": "window:mouseup", "update": "false", "force": true}
      ]
    },
    {
      "name": "dragX",
      "value": 0,
      "on": [
        {"events": "@nodeSymbols:mousedown", "update": "datum && isValid(datum.drawX) ? datum.drawX : dragX", "force": true},
        {"events": "window:mousemove", "update": "dragActive && dragId != null ? clamp(x(), 20, width - 20) : dragX", "force": true}
      ]
    },
    {
      "name": "dragY",
      "value": 0,
      "on": [
        {"events": "@nodeSymbols:mousedown", "update": "datum && isValid(datum.drawY) ? datum.drawY : dragY", "force": true},
        {"events": "window:mousemove", "update": "dragActive && dragId != null ? clamp(y(), 50, height - 20) : dragY", "force": true}
      ]
    },
    {
      "name": "hoverNode",
      "value": null,
      "on": [
        {"events": "@nodeSymbols:mouseover", "update": "dragActive ? null : datum"},
        {"events": "@nodeSymbols:mouseout", "update": "null"}
      ]
    },
    {
      "name": "tooltipX",
      "value": 0,
      "on": [
        {"events": "@nodeSymbols:mousemove", "update": "x()"},
        {"events": "@nodeSymbols:mouseover", "update": "x()"}
      ]
    },
    {
      "name": "tooltipY",
      "value": 0,
      "on": [
        {"events": "@nodeSymbols:mousemove", "update": "y()"},
        {"events": "@nodeSymbols:mouseover", "update": "y()"}
      ]
    },
    {"name": "nodeRadius", "value": 9},
    {"name": "cellPad", "value": 16}
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "index": "MALCOLM_NETWORK_INDEX_PATTERN_REPLACER",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                {"exists": {"field": "source.device.purdue_zone"}},
                {"exists": {"field": "destination.device.purdue_zone"}},
                "%dashboard_context-must_clause%"
              ],
              "must_not": ["%dashboard_context-must_not_clause%"],
              "filter": [
                {"exists": {"field": "source.ip"}},
                {"exists": {"field": "destination.ip"}},
                {"range": {"MALCOLM_NETWORK_INDEX_TIME_FIELD_REPLACER": {"%timefilter%": true}}},
                "%dashboard_context-filter_clause%"
              ]
            }
          },
          "aggs": {
            "connections": {
              "composite": {
                "size": 30000,
                "sources": [
                  {"src": {"terms": {"field": "source.ip"}}},
                  {"dst": {"terms": {"field": "destination.ip"}}}
                ]
              },
              "aggs": {
                "src_purdue": {"terms": {"field": "source.device.purdue_zone"}},
                "dst_purdue": {"terms": {"field": "destination.device.purdue_zone"}},
                "protocols": {"terms": {"field": "network.protocol"}},
                "network_types": {"terms": {"field": "network.type", "size": 5}}
              }
            }
          }
        }
      },
      "format": {"property": "aggregations.connections.buckets"},
      "transform": [
        {
          "type": "filter",
          "expr": "datum.doc_count >= minConnections"
        },
        {
          "type": "project",
          "fields": ["key.src", "key.dst", "doc_count", "protocols.buckets", "network_types.buckets", "src_purdue.buckets", "dst_purdue.buckets"],
          "as": ["src", "dst", "count", "protocols", "network_types", "src_purdue_zone", "dst_purdue_zone"]
        },
        {
          "type": "formula",
          "expr": "pluck(datum.src_purdue_zone, 'key')[0]",
          "as": "src_purdue_zone"
        },
        {
          "type": "formula",
          "expr": "pluck(datum.dst_purdue_zone, 'key')[0]",
          "as": "dst_purdue_zone"
        },
        {
          "type": "formula",
          "expr": "[datum.src_purdue_zone, datum.dst_purdue_zone]",
          "as": "purdue_zone"
        },
        {
          "type": "formula",
          "expr": "pluck(datum.network_types, 'key')",
          "as": "network_types"
        },
        {
          "type": "formula",
          "expr": "pluck(datum.protocols, 'key')",
          "as": "protocol_keys"
        },
        {
          "type": "filter",
          "expr": "!ipFilter || test(lower(ipFilter), lower(datum.src + datum.dst))"
        },
        {
          "type": "filter",
          "expr": "ipType === 'both' || indexof(datum.network_types, ipType) !== -1"
        },
        {
          "type": "filter",
          "expr": "protoFilter === '' || indexof(lower(join(datum.protocol_keys, ',')), lower(protoFilter)) >= 0"
        },
        {"type": "formula", "as": "protoStr", "expr": "join(datum.protocol_keys, ',')" },
      ]
    },
    {
      "name": "subnet-prefilter",
      "source": "raw",
      "transform": [
        {
          "type": "filter",
          "expr": "excludeSubnets === '' || (indexof(datum.src, excludeSubnets) < 0 && indexof(datum.dst, excludeSubnets) < 0)"
        },
      ]
    },
    {
      "name": "filtered-raw",
      "source": "raw",
      "transform": [
        {
          "type": "filter",
          "expr": "excludeSubnets === '' || (indexof(datum.src, excludeSubnets) < 0 && indexof(datum.dst, excludeSubnets) < 0) || length(data('subnet-prefilter')) < 1"
        },
        {
          "type": "filter",
          "expr": "excludeProtos === '' || indexof(lower(datum.protoStr), lower(excludeProtos)) < 0"
        },
      ]
    },
    {
      "name": "files-raw",
      "url": {
        "index": "MALCOLM_NETWORK_INDEX_PATTERN_REPLACER",
        "body": {
          "size": 500,
          "_source": [
            "source.ip",
            "destination.ip",
            "file.name",
            "file.mime_type",
            "file.size",
            "file.hash.sha256",
            "file.hash.sha1",
            "file.hash.md5",
            "file.hash.ssdeep",
            "event.risk_score",
            "event.severity_tags",
            "zeek.files.seen_bytes",
            "strelka.result.file.name",
            "strelka.result.flags",
            "strelka.result.scanners",
            "timestamp"
          ],
          "query": {
            "bool": {
              "filter": [
                { "term": { "event.category": "file" } },
                { "exists": { "field": "source.ip" } },
                { "exists": { "field": "destination.ip" } }
              ]
            }
          },
          "sort": [{ "timestamp": "desc" }]
        }
      },
      "format": { "property": "hits.hits" },
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum._source) && isValid(datum._source.source) && isValid(datum._source.destination) && isValid(datum._source.source.ip) && isValid(datum._source.destination.ip)"
        },
        { "type": "formula", "as": "src", "expr": "datum._source.source.ip" },
        { "type": "formula", "as": "dst", "expr": "datum._source.destination.ip" },
        {
          "type": "formula",
          "as": "fname",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.name) ? (isArray(datum._source.file.name) ? datum._source.file.name[0] : datum._source.file.name) : (isValid(datum._source.strelka) && isValid(datum._source.strelka.result) && isValid(datum._source.strelka.result.file) ? datum._source.strelka.result.file.name : '(unnamed)')"
        },
        {
          "type": "formula",
          "as": "mime",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.mime_type) ? (isArray(datum._source.file.mime_type) ? datum._source.file.mime_type[0] : datum._source.file.mime_type) : 'unknown'"
        },
        {
          "type": "formula",
          "as": "fsize",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.size) ? datum._source.file.size : (isValid(datum._source.zeek) && isValid(datum._source.zeek.files) && isValid(datum._source.zeek.files.seen_bytes) ? datum._source.zeek.files.seen_bytes : null)"
        },
        {
          "type": "formula",
          "as": "score",
          "expr": "isValid(datum._source.event) && isValid(datum._source.event.risk_score) ? datum._source.event.risk_score : 0"
        },
        {
          "type": "formula",
          "as": "sevTag",
          "expr": "isValid(datum._source.event) && isValid(datum._source.event.severity_tags) ? (isArray(datum._source.event.severity_tags) ? datum._source.event.severity_tags[0] : datum._source.event.severity_tags) : ''"
        },
        {
          "type": "formula",
          "as": "avFlag",
          "expr": "isValid(datum._source.strelka) && isValid(datum._source.strelka.result) && isValid(datum._source.strelka.result.flags) && isArray(datum._source.strelka.result.flags) && length(datum._source.strelka.result.flags) > 0"
        },
        {
          "type": "formula",
          "as": "sha256",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.hash) && isValid(datum._source.file.hash.sha256) ? (isArray(datum._source.file.hash.sha256) ? datum._source.file.hash.sha256[0] : datum._source.file.hash.sha256) : ''"
        },
        {
          "type": "formula",
          "as": "sha1",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.hash) && isValid(datum._source.file.hash.sha1) ? (isArray(datum._source.file.hash.sha1) ? datum._source.file.hash.sha1[0] : datum._source.file.hash.sha1) : ''"
        },
        {
          "type": "formula",
          "as": "md5",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.hash) && isValid(datum._source.file.hash.md5) ? (isArray(datum._source.file.hash.md5) ? datum._source.file.hash.md5[0] : datum._source.file.hash.md5) : ''"
        },
        {
          "type": "formula",
          "as": "ssdeep",
          "expr": "isValid(datum._source.file) && isValid(datum._source.file.hash) && isValid(datum._source.file.hash.ssdeep) ? (isArray(datum._source.file.hash.ssdeep) ? datum._source.file.hash.ssdeep[0] : datum._source.file.hash.ssdeep) : ''"
        },
        {
          "type": "formula",
          "as": "scanners",
          "expr": "isValid(datum._source.strelka) && isValid(datum._source.strelka.result) && isValid(datum._source.strelka.result.scanners) && isArray(datum._source.strelka.result.scanners) ? join(datum._source.strelka.result.scanners, ', ') : ''"
        },
        {
          "type": "formula",
          "as": "flagsStr",
          "expr": "isValid(datum._source.strelka) && isValid(datum._source.strelka.result) && isValid(datum._source.strelka.result.flags) && isArray(datum._source.strelka.result.flags) ? join(datum._source.strelka.result.flags, ', ') : ''"
        },
        { "type": "formula", "as": "ts", "expr": "isValid(datum._source['timestamp']) ? datum._source['timestamp'] : null" },
        // { "type": "filter", "expr": "datum.score >= minRiskScore" },
        {
          "type": "filter",
          "expr": "excludeSubnets === '' || (indexof(datum.src, excludeSubnets) < 0 && indexof(datum.dst, excludeSubnets) < 0 || length(data('subnet-prefilter')) < 1)"
        },
        // {
        //   "type": "filter",
        //   "expr": "ipFilter === '' || indexof(datum.src, ipFilter) >= 0 || indexof(datum.dst, ipFilter) >= 0"
        // }
        {
          "type": "filter",
          "expr": "!ipFilter || test(lower(ipFilter), lower(datum.src + datum.dst))"
        },
      ]
    },
    {
      "name": "ipToProtocol",
      "source": "filtered-raw",
      "transform": [
        {
          "type": "fold",
          "fields": ["src", "dst"],
          "as": ["_", "ip"]
        },
        // {
        //   "type": "formula",
        //   "expr": "isArray(datum.purdue_zone) && length(datum.purdue_zone) ? datum.purdue_zone : [null]",
        //   "as": "purdue_zone_keys"
        // },
        // {
        //   "type": "flatten",
        //   "fields": ["purdue_zone"],
        //   "as": ["purdue_zone"]
        // },
        {
          "type": "filter",
          "expr": "datum.purdue_zone != null"
        },
        {
          "type": "aggregate",
          "groupby": ["ip", "purdue_zone"]
        },
        // {
        //   "type": "aggregate",
        //   "groupby": ["ip"],
        //   "fields": ["purdue_zone"],
        //   "ops": ["values"],
        //   "as": ["rows"]
        // },
        // {
        //   "type": "formula",
        //   "expr": "pluck(datum.rows, 'purdue_zone')",
        //   "as": "purdue_zone"
        // },
        // {
        //   "type": "project",
        //   "fields": ["ip", "purdue_zone"]
        // }
      ]
    },
    {
      "name": "ipToProtocols",
      "source": "filtered-raw",
      "transform": [
        {
          "type": "fold",
          "fields": ["src", "dst"],
          "as": ["_", "ip"]
        },
        {
          "type": "aggregate",
          "groupby": ["ip"],
          "fields": ["count"],
          "ops": ["sum"],
          "as": ["count"]
        },
        {
          "type": "lookup",
          "from": "ipToProtocol",
          "key": "ip",
          "fields": ["ip"],
          "values": ["purdue_zone"],
          "as": ["purdue_zone"]
        },
        // {
        //   "type": "formula",
        //   "expr": "isValid(datum.purdue_zone) ? datum.purdue_zone : []",
        //   "as": "purdue_zone"
        // },
        {
          "type": "formula",
          "expr": "indexof(datum.purdue_zone, 'ot') === 0",
          "as": "is_ics"
        },
        {
          "type": "formula",
          "expr": "indexof(datum.purdue_zone, 'dmz') === 0",
          "as": "is_dmz"
        },
        {
          "type": "formula",
          "expr": "indexof(datum.purdue_zone, 'it') === 0",
          "as": "is_gen"
        },
        {
          "type": "formula",
          "expr": "if(datum.is_ics, 'ICS', if(datum.is_dmz, 'DMZ', if(datum.is_gen, 'GEN', null)))",
          "as": "zone"
        }
      ]
    },
    {
      "name": "zone-ips",
      "source": "filtered-raw",
      "transform": [
        {
          "type": "lookup",
          "from": "ipToProtocols",
          "key": "ip",
          "fields": ["dst"],
          "values": ["zone"],
          "as": ["dst_zone"],
          "default": false
        },
        {
          "type": "lookup",
          "from": "ipToProtocols",
          "key": "ip",
          "fields": ["src"],
          "values": ["zone"],
          "as": ["src_zone"],
          "default": false
        },
        {
          "type": "formula",
          "expr": "datum.src_zone + '-' + datum.dst_zone",
          "as": "zone"
        }
      ]
    },
    {
      "name": "degrees",
      "source": "zone-ips",
      "transform": [
        {"type": "fold", "fields": ["src", "dst"], "as": ["_", "id"]},
        {"type": "joinaggregate", "groupby": ["id"], "ops": ["count"], "as": ["degree"]}
      ]
    },
    {
      "name": "dmz-ics-ips",
      "source": "zone-ips",
      "transform": [
        {"type": "filter", "expr": "datum.zone === 'DMZ-ICS' || datum.zone === 'ICS-DMZ'"},
        // todo keep empty until needed to save memory
        {"type": "fold", "fields": ["src", "dst"], "as": ["_", "ip"]},
        {"type": "aggregate", "groupby": ["ip"]}
      ]
    },
    {
      "name": "general-ics-ips",
      "source": "zone-ips",
      "transform": [
        {"type": "filter", "expr": "datum.zone === 'GEN-ICS' || datum.zone === 'ICS-GEN'"},
        {"type": "fold", "fields": ["src", "dst"], "as": ["_", "ip"]},
        {"type": "aggregate", "groupby": ["ip"]}
      ]
    },
    {
      "name": "cross-zone-ips",
      "source": "zone-ips",
      "transform": [
        {"type": "filter", "expr": "datum.src_zone !== datum.dst_zone"},
        {"type": "fold", "fields": ["src", "dst"], "as": ["_", "ip"]},
        {"type": "aggregate", "groupby": ["ip"]}
      ]
    },
    {
      "name": "same-zone-ips",
      "source": "zone-ips",
      "transform": [
        {"type": "filter", "expr": "datum.src_zone === datum.dst_zone"},
        {"type": "fold", "fields": ["src", "dst"], "as": ["_", "ip"]},
        {"type": "aggregate", "groupby": ["ip"]}
      ]
    },
