          "key": "ip",
          "fields": ["ip"],
          "values": ["ip"],
          "as": ["is_cross_zone"],
          "default": null
        },
        {"type": "filter", "expr": "datum.is_cross_zone === null"}
      ]
    },
    {
      // todo simplify
      "name": "full-chain-ips",
      "source": "zone-ips",
      "transform": [
        {"type": "filter", "expr": "datum.zone === 'DMZ-ICS' || datum.zone === 'ICS-DMZ'"},
        // todo keep empty until needed to save memory
        {"type": "formula", "as": "dmz_ip", "expr": "datum.src"},
        {"type": "formula", "as": "ics_ip", "expr": "datum.dst"},
        {"type": "lookup", "from": "zone-ips", "key": "dst", "fields": ["dmz_ip"], "as": ["gen_to_dmz_edge"]},
        {
          "type": "filter",
          "expr": "datum.gen_to_dmz_edge != null && datum.gen_to_dmz_edge.src_zone === 'GEN'"
        },
        {"type": "formula", "as": "general_ip", "expr": "datum.gen_to_dmz_edge.src"},
        {"type": "fold", "fields": ["general_ip", "dmz_ip", "ics_ip"], "as": ["_", "ip"]},
        {"type": "aggregate", "groupby": ["ip"]}
      ]
    },
    {
      "name": "sections",
      "source": "ipToProtocols",
      "transform": [
        {"type": "aggregate", "groupby": ["zone"], "ops": ["count"], "as": ["nodeCount"]},
        {"type": "formula", "as": "order", "expr": "indexof(['GEN','DMZ','ICS'], datum.zone)"},
        {"type": "formula", "as": "label", "expr": "slice([['General', 'Network'], 'DMZ', 'ICS / OT'], datum.order)[0]"},
        {"type": "collect", "sort": {"field": "order"}},
        {"type": "formula", "as": "cell", "expr": "2*nodeRadius + cellPad"},
        {"type": "formula", "as": "maxRows", "expr": "max(1, floor(usableHeight / datum.cell))"},
        {"type": "formula", "as": "cols", "expr": "max(1, ceil(datum.nodeCount / datum.maxRows))"},
        {
          "type": "window", "sort": {"field": "order"}, "ops": ["sum"], "fields": ["cols"], "as": ["cumCols"],
          "frame": [null, 0]
        },
        {"type": "joinaggregate", "ops": ["sum"], "fields": ["cols"], "as": ["totalCols"]},
        {"type": "formula", "as": "fracEnd", "expr": "datum.cumCols / datum.totalCols"},
        {"type": "formula", "as": "fracStart", "expr": "(datum.cumCols - datum.cols) / datum.totalCols"},
        {"type": "formula", "as": "fracCenter", "expr": "(datum.fracStart + datum.fracEnd) / 2"}
      ]
    },
    {
      "name": "nodes",
      "source": "ipToProtocols",
      "transform": [
        {"type": "formula", "as": "id", "expr": "datum.ip"},
        {
          "type": "lookup",
          "from": "sections",
          "key": "zone",
          "fields": ["zone"],
          "values": ["fracStart", "fracEnd", "fracCenter", "nodeCount"],
          "as": ["fracStart", "fracEnd", "fracCenter", "zoneCount"]
        },
        {"type": "lookup", "from": "degrees", "key": "id", "fields": ["ip"], "values": ["degree"], "as": ["degree"]},
        {"type": "formula", "as": "degree", "expr": "isValid(datum.degree) ? datum.degree : 0"},
        {
          "type": "window",
          "groupby": ["zone"],
          "sort": {"field": "degree", "order": "descending"},
          "ops": ["row_number"],
          "as": ["degRank"]
        },
        {"type": "formula", "as": "k0", "expr": "datum.degRank - 1"},
        {"type": "formula", "as": "bandLeft", "expr": "leftPad + datum.fracStart * usableWidth"},
        {"type": "formula", "as": "bandW", "expr": "(datum.fracEnd - datum.fracStart) * usableWidth"},
        {"type": "formula", "as": "cell", "expr": "2 * nodeRadius + cellPad"},
        {"type": "formula", "as": "maxRows", "expr": "max(1, floor(usableHeight / datum.cell))"},
        {"type": "formula", "as": "cols", "expr": "max(1, ceil(datum.zoneCount / datum.maxRows))"},
        {"type": "formula", "as": "rows", "expr": "ceil(datum.zoneCount / datum.cols)"},
        {"type": "formula", "as": "col", "expr": "floor(datum.k0 / datum.rows)"},
        {"type": "formula", "as": "row", "expr": "datum.k0 % datum.rows"},
        {"type": "formula", "as": "colW", "expr": "datum.bandW / datum.cols"},
        // Align nodes with the highest degree rank to the inside
        {"type": "formula", "as": "side", "expr": "datum.fracCenter < 0.5 ? -1 : (datum.fracCenter > 0.5 ? 1 : 0)"},
        {
          "type": "formula", "as": "colOriented",
          "expr": "datum.side > 0 ? datum.col : (datum.side < 0 ? (datum.cols - 1 - datum.col) : (floor((datum.cols - 1) / 2) + ((datum.col % 2 === 1) ? 1 : -1) * ceil(datum.col / 2)))"
        },
        {"type": "formula", "as": "jitterSpread", "expr": "0.8"},
        {"type": "formula", "as": "jitterFrac", "expr": "(datum.row * goldenRatio) % 1"},
        {"type": "formula", "as": "jitterX", "expr": "(datum.jitterFrac - 0.5) * datum.colW * datum.jitterSpread"},
        {
          "type": "formula",
          "as": "baseX",
          "expr": "datum.bandLeft + (datum.colOriented + 0.5) * datum.colW + datum.jitterX"
        },
        {
          "type": "formula",
          "as": "baseY",
          "expr": "datum.rows === 1 ? topPad + usableHeight/2 : topPad + (datum.row + 0.5) / datum.rows * usableHeight + ((datum.k % 2) === 0 ? -6 : 6)"
        }
      ]
    },
    {
      "name": "nodePositions",
      "values": [],
      "on": [
        {"trigger": "dragActive && dragId != null", "remove": "datum && datum.id === dragId"},
        {"trigger": "dragActive && dragId != null", "insert": "{id: dragId, drawX: dragX, drawY: dragY}"}
      ]
    },
    {
      "name": "displayNodes",
