        {"type": "lookup", "from": "visibleNodes", "key": "id", "fields": ["dst"], "as": ["targetNode"]},
        {"type": "filter", "expr": "datum.sourceNode != null && datum.targetNode != null"},
        {"type": "formula", "as": "pairKey", "expr": "datum.src + '|' + datum.dst"},
