        { "type": "formula", "as": "hasFileLink", "expr": "datum.fileLinkInfo != null" },
        { "type": "formula", "as": "offset", "expr": "datum.hasFileLink ? (datum.hasReverse ? 5 : 0) : (datum.hasReverse ? 10 : 0)" },        {"type": "formula", "as": "dx", "expr": "datum.targetNode.drawX - datum.sourceNode.drawX"},
        {"type": "formula", "as": "dy", "expr": "datum.targetNode.drawY - datum.sourceNode.drawY"},
