        }, // todo
        {"type": "formula", "as": "lineX1", "expr": "datum.sourceNode.drawX + datum.nx * datum.offset"},
        {"type": "formula", "as": "lineY1", "expr": "datum.sourceNode.drawY + datum.ny * datum.offset"},
        {"type": "formula", "as": "lineX2", "expr": "datum.targetNode.drawX + datum.nx * datum.offset"},
        {"type": "formula", "as": "lineY2", "expr": "datum.targetNode.drawY + datum.ny * datum.offset"},
        // todo check these
        {
